/* ── Panic ─────────────────────────────────────────────────────────── */

void ruxen_panic(const char *message) {
    fflush(stdout);
    fprintf(stderr, "ruxen panic: %s\n", message ? message : "(unknown)");
    fflush(stderr);
    exit(101);
}
